       --panel: rgba(255, 255, 255, 0.88);
       --panel-strong: #ffffff;
       --text: #102033;
       --muted: #5f6f82;
       --line: rgba(16, 32, 51, 0.1);
       --shadow: 0 24px 60px rgba(15, 23, 42, 0.18);
       --primary: #2563eb;
       --danger: #dc2626;
       --danger-dark: #b91c1c;
       --overlay: rgba(9, 15, 26, 0.55);
       --radius: 24px;
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top, rgba(37, 99, 235, 0.12), transparent 28%),
         linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
       color: var(--text);
       display: grid;
       place-items: center;
       padding: 32px 20px;
     }

     .page-shell {
       width: min(100%, 1040px);
     }

     .preview-card {
       display: grid;
       grid-template-columns: minmax(0, 1.2fr) minmax(300px, 0.8fr);
       gap: 28px;
       align-items: stretch;
       background: var(--panel);
       border: 1px solid rgba(255, 255, 255, 0.7);
       backdrop-filter: blur(18px);
       border-radius: 32px;
       box-shadow: var(--shadow);
       overflow: hidden;
     }

     .image-frame {
       position: relative;
       min-height: 520px;
       background:
         linear-gradient(180deg, rgba(15, 23, 42, 0.1), rgba(15, 23, 42, 0.3)),
         url("https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80") center / cover;
     }

     .image-badge {
       position: absolute;
       top: 24px;
       left: 24px;
       padding: 10px 14px;
       border-radius: 999px;
       background: rgba(255, 255, 255, 0.88);
       color: var(--text);
       font-size: 0.9rem;
       font-weight: 600;
       letter-spacing: 0.01em;
       box-shadow: 0 10px 25px rgba(15, 23, 42, 0.12);
     }

     .details {
       padding: 36px;
       display: flex;
       flex-direction: column;
       justify-content: center;
       background: linear-gradient(180deg, rgba(255, 255, 255, 0.72), var(--panel-strong));
     }

     .eyebrow {
       margin: 0 0 12px;
       color: var(--primary);
       font-size: 0.85rem;
       font-weight: 700;
       text-transform: uppercase;
       letter-spacing: 0.12em;
     }

     h1 {
       margin: 0;
       font-size: clamp(2rem, 3vw, 3rem);
       line-height: 1.05;
     }

     .description {
       margin: 16px 0 24px;
       color: var(--muted);
       font-size: 1rem;
       line-height: 1.65;
       max-width: 34ch;
     }

     .meta {
       display: grid;
       grid-template-columns: repeat(2, minmax(0, 1fr));
       gap: 14px;
       margin-bottom: 28px;
     }

     .meta-card {
       padding: 16px;
       border-radius: 18px;
       background: #f8fbff;
       border: 1px solid var(--line);
     }

     .meta-label {
       display: block;
       color: var(--muted);
       font-size: 0.85rem;
       margin-bottom: 6px;
     }

     .meta-value {
       font-weight: 700;
       font-size: 1rem;
     }

     .actions {
       display: flex;
       gap: 12px;
       flex-wrap: wrap;
       margin-top: auto;
     }

     button {
       appearance: none;
       border: 0;
       border-radius: 16px;
       padding: 14px 20px;
       font: inherit;
       font-weight: 700;
       cursor: pointer;
       transition: transform 160ms ease, box-shadow 160ms ease, background-color 160ms ease, opacity 160ms ease;
     }

     button:hover {
       transform: translateY(-1px);
     }

     button:focus-visible {
       outline: 3px solid rgba(37, 99, 235, 0.3);
       outline-offset: 2px;
     }

     .secondary {
       background: #eef4ff;
       color: var(--primary);
     }

     .trigger {
       background: rgba(220, 38, 38, 0.1);
       color: var(--danger);
     }

     .modal[hidden] {
       display: none;
     }

     .modal {
       position: fixed;
       inset: 0;
       display: grid;
       place-items: center;
       padding: 20px;
       z-index: 20;
     }

     .modal__backdrop {
       position: absolute;
       inset: 0;
       background: var(--overlay);
     }

     .modal__dialog {
       position: relative;
       width: min(100%, 460px);
       padding: 28px;
       border-radius: var(--radius);
       background: rgba(255, 255, 255, 0.98);
       box-shadow: 0 30px 70px rgba(15, 23, 42, 0.3);
       border: 1px solid rgba(255, 255, 255, 0.8);
       z-index: 1;
     }

     .dialog-icon {
       width: 56px;
       height: 56px;
       display: grid;
       place-items: center;
       border-radius: 18px;
       margin-bottom: 18px;
       color: var(--danger);
       background: rgba(220, 38, 38, 0.12);
       font-size: 1.5rem;
       font-weight: 800;
     }

     .modal h2 {
       margin: 0 0 10px;
       font-size: 1.5rem;
       line-height: 1.2;
     }

     .modal p {
       margin: 0 0 24px;
       color: var(--muted);
       line-height: 1.6;
     }

     .modal__actions {
       display: flex;
       justify-content: flex-end;
       gap: 12px;
       flex-wrap: wrap;
     }

     .ghost {
       background: #f4f7fb;
       color: var(--text);
     }

     .danger {
       background: var(--danger);
       color: #fff;
       box-shadow: 0 12px 24px rgba(220, 38, 38, 0.24);
     }

     .danger:hover {
       background: var(--danger-dark);
     }

     .status {
       margin-top: 18px;
       min-height: 1.5em;
       color: var(--primary);
       font-weight: 600;
     }

     @media (max-width: 860px) {
       .preview-card {
         grid-template-columns: 1fr;
')

